@Composable
fun UserStatus(categoryStatus: String, statusValue: String? = "No Information") {
    Card(
        modifier = Modifier.size(180.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Red)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Text(
                text = categoryStatus,
                color = Color.White,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center
            )

            Icon(
                imageVector = if (categoryStatus == "Smoking") Icons.Default.Clear else Icons.Default.Check, // CHANGE THIS TO A RELEVANT ICON
                contentDescription = "statusIcon",
                tint = Color.White,
                modifier = Modifier
                    .size(32.dp)
                    .padding(vertical = 8.dp)
            )

            Text(
                text = statusValue ?: "No Information",
                color = Color.White,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center
            )
        }
    }
}

package com.kelompok6.hyperaid.ui.screens.vitalsync

import android.app.Application
import android.content.Context
import androidx.lifecycle.AndroidViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

class VitalsyncViewModel(application: Application) : AndroidViewModel(application) {
    private val prefs = application.getSharedPreferences("vitalsync_prefs", Context.MODE_PRIVATE)

    private val _sfigConnected = MutableStateFlow(prefs.getBoolean("sfig_connected", false))
    val sfigConnected: StateFlow<Boolean> = _sfigConnected.asStateFlow()

    private val _lastNotes = MutableStateFlow<Map<String, String>?>(null)
    val lastNotes: StateFlow<Map<String, String>?> = _lastNotes.asStateFlow()

    fun setSfigConnected(connected: Boolean) {
        _sfigConnected.value = connected
        prefs.edit().putBoolean("sfig_connected", connected).apply()
    }

    fun setLastNotes(notes: Map<String, String>?) {
        _lastNotes.value = notes
        // not persisted for now
    }
}

